insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'La mia mappa del cyberspace', 'Scegli 3 servizi che usi ogni giorno e seguili strato per strato: risolvi il dominio, esegui tracert, scopri con RDAP a chi è assegnato l''IP e compila per ognuno la tabella dei tre livelli. Chiudi con una riflessione su paesi e leggi coinvolti e consegna il file mappa-cyberspace-cognome.pdf.', null, '2026-10-30', (select id from topics where class_id = '5g' and title = 'Il cyberspace' limit 1), 'contenuti/compiti/cyberspace.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'La mia mappa del cyberspace');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Consulente per un giorno', 'Per un''azienda inventata ma realistica elenca almeno 8 asset con i valori CIA, compila un registro di almeno 10 rischi con R = P × I, livello e trattamento, e prepara un piano con RTO, RPO, contromisure per funzione NIST CSF 2.0 e una valutazione NIS2. Consegna il file consulente-cognome.ods con i fogli Asset, Rischi e Piano.', null, '2026-11-04', (select id from topics where class_id = '5g' and title = 'Le basi della cybersecurity aziendale' limit 1), 'contenuti/compiti/cybersecurity-aziendale.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Consulente per un giorno');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Anatomia di un attacco vero', 'Scegli un attacco documentato (per esempio WannaCry, NotPetya o Colonial Pipeline) e, con almeno 3 fonti affidabili, descrivi il profilo dell''attaccante, le 7 fasi della kill chain, almeno 5 tecniche MITRE ATT&CK, l''impatto e le due contromisure che l''avrebbero fermato prima. Consegna il file attacco-cognome.pdf.', null, '2026-11-09', (select id from topics where class_id = '5g' and title = 'Attaccanti: i Cybercriminali' limit 1), 'contenuti/compiti/cybercriminali.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Anatomia di un attacco vero');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il mio SIEM fa un passo avanti', 'Estendi il MiniSiem.java della lezione con la regola del viaggio impossibile (stesso utente, accessi riusciti da paesi diversi a meno di 60 minuti), mantenendo quella del brute force, e prova tutto con un log di almeno 12 righe. Nel README indica output atteso, tecniche ATT&CK e falsi positivi possibili; consegna il file siem-cognome.zip.', null, '2026-11-12', (select id from topics where class_id = '5g' and title = 'Difensori: gli esperti di Cybersecurity (cyberdefender)' limit 1), 'contenuti/compiti/cyberdefender.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il mio SIEM fa un passo avanti');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Tre falle nel negozio', 'Avvia OWASP Juice Shop sul tuo computer e risolvi 3 nuove sfide da 1 o 2 stelle. Per ognuna indica la categoria OWASP Top 10, i passi fatti con una schermata, la causa dell''errore e la correzione con un frammento di codice o di configurazione. Consegna il file juice-shop-cognome.pdf.', null, '2026-11-18', (select id from topics where class_id = '5g' and title = 'Network e Web App Security' limit 1), 'contenuti/compiti/network-web-security.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Tre falle nel negozio');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'La mia prima write-up', 'Supera almeno 4 nuovi livelli di OverTheWire Bandit e una sfida di picoGym di una categoria diversa da General Skills, e documenta ognuno con obiettivo, idea, comandi e che cosa hai imparato, senza scrivere le password. Chiudi con quale categoria vorresti approfondire e consegna il file writeup-cognome.md.', null, '2026-11-23', (select id from topics where class_id = '5g' and title = 'Cyberchallenge: Capture the Flag' limit 1), 'contenuti/compiti/capture-the-flag.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'La mia prima write-up');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Autopsia di un disservizio', 'Scegli il resoconto ufficiale (post-mortem) di un disservizio reale di un grande servizio online e analizzalo: cronologia, causa radice, propagazione del guasto, fallacie del calcolo distribuito dimostrate, scelta tra coerenza e disponibilità e contromisure. Consegna il file autopsia-cognome.pdf.', null, '2026-11-26', (select id from topics where class_id = '5g' and title = 'I sistemi distribuiti' limit 1), 'contenuti/compiti/sistemi-distribuiti.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Autopsia di un disservizio');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il registro remoto con Java RMI', 'Scrivi un servizio Java RMI che conserva i voti degli studenti con le operazioni aggiungiVoto e media, con controllo dei valori non validi, e un client che lo usa. Rispondi poi a tre domande su ritrasmissioni, idempotenza e RemoteException. Consegna il file registro-rmi-cognome.zip con i sorgenti e risposte.txt.', null, '2026-12-01', (select id from topics where class_id = '5g' and title = 'La comunicazione con RPC' limit 1), 'contenuti/compiti/comunicazione-rpc.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il registro remoto con Java RMI');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il cinema multisala a servizi', 'Progetta l''architettura a servizi per la vendita di biglietti di una catena di cinema: servizi e dati, tabella delle rotte dell''API gateway, flusso di acquisto, gestione dei guasti e del posto conteso, giustificazione della scelta tra microservizi e monolite. Consegna il file cinema-architettura-cognome.pdf.', null, '2026-12-04', (select id from topics where class_id = '5g' and title = 'Le architetture orientate ai servizi' limit 1), 'contenuti/compiti/architetture-soa.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il cinema multisala a servizi');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il cambio del giorno: da XML a JSON', 'Scrivi un programma Java che legge con il parser XML del JDK i cambi dell''euro pubblicati dalla Banca Centrale Europea e produce un file JSON valido con data e quattro valute, gestendo l''errore di rete. Consegna il file cambi-cognome.zip con Cambi.java, cambi.json e risposte.txt.', null, '2026-12-10', (select id from topics where class_id = '5g' and title = 'I web service' limit 1), 'contenuti/compiti/web-service.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il cambio del giorno: da XML a JSON');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Detective HTTP', 'Cattura con curl o DevTools sei scambi HTTP reali con codici diversi (200, 3xx, 304, 404, 401 o 403, 405), spiega riga per riga uno scambio, scrivi a mano una richiesta POST con il Content-Length esatto e chiarisci la differenza tra metodi sicuri e idempotenti. Consegna il file detective-http-cognome.pdf.', null, '2026-12-15', (select id from topics where class_id = '5g' and title = 'I web service e il protocollo HTTP' limit 1), 'contenuti/compiti/protocollo-http.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Detective HTTP');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Partite IVA d''Europa: un servizio SOAP vero', 'Analizza il WSDL pubblico del servizio europeo VIES, scrivi a mano la busta SOAP per l''operazione checkVat e inviala con curl, prova i casi d''errore e disegna lo schema del WSDL. Consegna il file vies-cognome.zip con checkvat.xml, risposta.xml e analisi.pdf.', null, '2026-12-21', (select id from topics where class_id = '5g' and title = 'I web service con SOAP' limit 1), 'contenuti/compiti/soap-wsdl.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Partite IVA d''Europa: un servizio SOAP vero');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il servizio Pagella', 'Crea con Maven un servizio SOAP che trasforma un voto in giudizio e calcola la media di una lista di voti, con validazione dello schema e Fault per i valori non validi, prova cinque buste con curl e scrivi un client generato con wsimport. Consegna il file pagella-soap-cognome.zip con i due progetti senza target, le buste e prove.txt.', null, '2027-01-08', (select id from topics where class_id = '5g' and title = 'Web service SOAP in Java' limit 1), 'contenuti/compiti/soap-java.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il servizio Pagella');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'L''API delle prenotazioni dei laboratori', 'Progetta l''API REST con cui i docenti prenotano i laboratori della scuola: risorse e URI, una tabella di almeno 10 endpoint con metodi e codici di stato, esempi JSON e tre scelte motivate (prenotazione doppia, PUT o PATCH, filtri), più l''analisi della documentazione di Open-Meteo. Consegna il file api-prenotazioni-cognome.pdf.', null, '2027-01-13', (select id from topics where class_id = '5g' and title = 'I web service con REST' limit 1), 'contenuti/compiti/rest-web-service.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'L''API delle prenotazioni dei laboratori');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'BiblioAPI: arrivano i prestiti', 'Estendi il BiblioServer scritto in classe con la risorsa prestiti: prestito di un libro con 201, 404 e 409 se è già prestato, elenco con il filtro attivi=true, restituzione con PUT e filtro dei libri per autore. Consegna il file biblioapi-prestiti-cognome.zip con BiblioServer.java e prove.txt con l''output di curl.', null, '2027-01-18', (select id from topics where class_id = '5g' and title = 'Sviluppo di un web service RESTful in Java' limit 1), 'contenuti/compiti/rest-java.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'BiblioAPI: arrivano i prestiti');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'BiblioCLI: la biblioteca dal terminale', 'Scrivi un client Java a menu che usa BiblioAPI per elencare, cercare, aggiungere, modificare ed eliminare libri, gestendo 404, 400, input non valido e server spento senza mai crollare; bonus una pagina cerca.jsp. Consegna il file bibliocli-cognome.zip con BiblioCLI.java e sessione.txt.', null, '2027-01-21', (select id from topics where class_id = '5g' and title = 'Utilizzo di web service REST in Java e JSP' limit 1), 'contenuti/compiti/rest-client-jsp.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'BiblioCLI: la biblioteca dal terminale');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Collaudatore di API per un giorno', 'Porta la collezione di test di BiblioAPI ad almeno 12 richieste con variabili e test automatici, di cui almeno 6 casi negativi, eseguila con il Runner e scrivi un rapporto con la tabella dei casi di test e i difetti trovati. Consegna il file collaudo-cognome.zip con la collezione esportata e collaudo-cognome.pdf.', null, '2027-01-26', (select id from topics where class_id = '5g' and title = 'Test di web service REST con Curl e Postman' limit 1), 'contenuti/compiti/rest-curl-postman.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Collaudatore di API per un giorno');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il meteo della gita', 'Costruisci una pagina web che chiama in parallelo l''API di Open-Meteo per tre mete, mostra in una tabella temperatura massima e probabilità di pioggia dei prossimi giorni e indica la meta e il giorno migliori per la gita, gestendo gli errori. Consegna il file meteo-gita-cognome.zip con meteo-gita.html e uno screenshot.', null, '2027-01-29', (select id from topics where class_id = '5g' and title = 'Utilizzo di web service REST in JavaScript' limit 1), 'contenuti/compiti/rest-javascript.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il meteo della gita');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il diario della latenza', 'Completa PingSistema.java, che lancia il ping del sistema con ProcessBuilder, calcola minimo, media, massimo, jitter e perdita e aggiunge una riga a un CSV; misura tre destinazioni in momenti diversi e spiega i risultati in una relazione di una pagina. Consegna il file latenza-cognome.zip con PingSistema.java, Statistiche.java, latenza.csv e relazione.pdf.', null, '2027-02-04', (select id from topics where class_id = '5g' and title = 'L''efficienza della comunicazione: il ping' limit 1), 'contenuti/compiti/ping-java.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il diario della latenza');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il cruscotto della rete', 'Scrivi Cruscotto.java, che controlla in parallelo una lista di host e servizi (ICMP e TCP) con tre strategie (sequenziale, pool fisso, virtual thread), ne misura i tempi e genera una pagina HTML di stato; commenta i tempi ottenuti. Consegna il file cruscotto-cognome.zip con Cruscotto.java, controlli.txt, cruscotto.html e tempi.txt.', null, '2027-02-09', (select id from topics where class_id = '5g' and title = 'Il controllo della rete: il ping multiplo' limit 1), 'contenuti/compiti/ping-multiplo.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il cruscotto della rete');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Chat 2.0: nuovi comandi', 'Estendi la chat del laboratorio con nickname unici, il comando LIST e i messaggi privati PRIV, usa i virtual thread e documenta il protocollo; anche in gruppo fino a 3 persone. Consegna il file chat-cognome.zip con i tre file Java, protocollo.md e prova.pdf con gli screenshot di tre client.', null, '2027-02-12', (select id from topics where class_id = '5g' and title = 'La comunicazione socket: la chat' limit 1), 'contenuti/compiti/chat-socket.pdf', true where not exists (select 1 from assignments where class_id = '5g' and title = 'Chat 2.0: nuovi comandi');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il sondaggio in diretta', 'Realizza un sondaggio in tempo reale: il browser invia i voti via WebSocket e il server (Tomcat o il server alternativo solo JDK allegato) manda a tutti i conteggi in JSON, aggiornando le barre su ogni schermo; anche in gruppo fino a 3 persone. Consegna il file sondaggio-cognome.zip con il server, index.html e prova.pdf.', null, '2027-02-17', (select id from topics where class_id = '5g' and title = 'La comunicazione WebSocket tra browser e server' limit 1), 'contenuti/compiti/websocket-chat.pdf', true where not exists (select 1 from assignments where class_id = '5g' and title = 'Il sondaggio in diretta');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'La pagella mobile di un''app', 'Scegli un''app che usi ogni giorno e misurane consumo di batteria (in Wh), dati, permessi e comportamento con una rete lenta, poi indica se è nativa, web, ibrida o multipiattaforma e proponi tre miglioramenti legati ai vincoli dei dispositivi mobili. Consegna il file pagella-app-cognome.pdf.', null, '2027-02-22', (select id from topics where class_id = '5g' and title = 'Caratteristiche e problematiche' limit 1), 'contenuti/compiti/mobile-caratteristiche.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'La pagella mobile di un''app');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il mio telefono ai raggi X', 'Fai il controllo di sicurezza del tuo telefono: versione di Android e patch, audit dei permessi di sei app con la revoca di quelli inutili, poi prevedi i callback del ciclo di vita in tre scenari e spiega il problema della rotazione. Consegna il file raggi-x-cognome.pdf.', null, '2027-02-25', (select id from topics where class_id = '5g' and title = 'Il sistema operativo Android' limit 1), 'contenuti/compiti/android-sistema.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il mio telefono ai raggi X');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Traduci la pagella in Kotlin', 'Riscrivi in Kotlin idiomatico un programma Java che stampa una pagella con un voto mancante, usando data class, tipo nullable senza !!, when e lambda, e ottieni lo stesso output. Consegna il file traduzione-cognome.kt con l''output in un commento finale.', null, '2027-03-03', (select id from topics where class_id = '5g' and title = 'Conoscere Kotlin per sviluppare App Android' limit 1), 'contenuti/compiti/kotlin-base.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Traduci la pagella in Kotlin');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'QuizTPSI ha un''identità', 'Personalizza nome e icona della tua app, poi provoca sei situazioni (rotazione, Home, notifiche, blocco schermo, Indietro…) scrivendo prima la previsione e poi i callback che compaiono davvero in Logcat, con tre screenshot e tre brevi risposte. Consegna il file prima-app-cognome.pdf.', null, '2027-03-08', (select id from topics where class_id = '5g' and title = 'La prima App in Android Studio' limit 1), 'contenuti/compiti/android-prima-app.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'QuizTPSI ha un''identità');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Una schermata per tutti', 'Completa la schermata della domanda con tre domande e immagini, sposta tutti i testi nelle risorse e crea la traduzione inglese, poi verifica il layout con i caratteri al massimo e correggi ciò che si taglia. Consegna il file layout-cognome.zip con layout, stringhe, note.txt e tre screenshot.', null, '2027-03-11', (select id from topics where class_id = '5g' and title = 'La modifica del layout: TextView e ImageView' limit 1), 'contenuti/compiti/android-layout.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Una schermata per tutti');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Un quiz a prova di utente', 'Porta QuizTPSI a cinque domande, aggiungi un pulsante Aiuto con suggerimento in un Toast e una penalità sul punteggio, impedisci le risposte doppie e salva tutto lo stato alla rotazione, documentando almeno sei test. Consegna il file quiz-cognome.zip con app/src/main e test.txt.', null, '2027-03-16', (select id from topics where class_id = '5g' and title = 'L''interattività: Button e Toast' limit 1), 'contenuti/compiti/android-button-toast.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Un quiz a prova di utente');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'QuizTPSI 1.0', 'Completa l''app con la schermata del risultato e un messaggio scelto con when, Gioca ancora con finish(), condivisione e una InfoActivity che apre una pagina web, poi disegna il diagramma di navigazione con Intent, dati e back stack. Consegna il file quiztpsi-cognome.zip con app/src/main e navigazione.pdf.', null, '2027-03-19', (select id from topics where class_id = '5g' and title = 'Una nuova pagina: Intent e New Activity' limit 1), 'contenuti/compiti/android-intent.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'QuizTPSI 1.0');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il brief del nostro cliente (lavoro di gruppo)', 'La squadra sceglie un cliente vero (associazione del territorio o club della scuola), lo intervista e scrive il brief con obiettivi SMART, due personas, sei user story, almeno dieci requisiti F/NF con priorità MoSCoW, la scelta tecnologica motivata e il calendario. Il referente consegna il file u5-brief-squadraN.pdf.', null, '2027-03-24', (select id from topics where class_id = '5g' and title = 'Il progetto di un sito' limit 1), 'contenuti/compiti/progetto-sito.pdf', true where not exists (select 1 from assignments where class_id = '5g' and title = 'Il brief del nostro cliente (lavoro di gruppo)');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Mappa del sito e wireframe (lavoro di gruppo)', 'La squadra completa l''inventario dei contenuti, fa un card sorting con tre persone esterne, disegna la mappa del sito e i wireframe mobile e desktop di tre pagine, e li prova con due persone. Il referente consegna il file u5-mappa-wireframe-squadraN.pdf.', null, '2027-04-02', (select id from topics where class_id = '5g' and title = 'Progetto generale del sito' limit 1), 'contenuti/compiti/mappa-sito.pdf', true where not exists (select 1 from assignments where class_id = '5g' and title = 'Mappa del sito e wireframe (lavoro di gruppo)');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'La home responsive (lavoro di gruppo)', 'La squadra realizza la home del sito in HTML semantico e CSS mobile first, con guida di stile in variabili CSS e contrasti verificati, immagini ottimizzate e misure Lighthouse prima e dopo. Il referente consegna il file u5-responsive-squadraN.zip con codice, screenshot a tre larghezze e lighthouse.md.', null, '2027-04-08', (select id from topics where class_id = '5g' and title = 'Problematiche di Web Design' limit 1), 'contenuti/compiti/web-design.pdf', true where not exists (select 1 from assignments where class_id = '5g' and title = 'La home responsive (lavoro di gruppo)');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Farsi trovare (lavoro di gruppo)', 'La squadra individua le ricerche reali degli utenti, scrive title e description per ogni pagina, prepara sitemap.xml, robots.txt e dati strutturati JSON-LD validati, porta Lighthouse SEO a 100 e riflette su come il sito potrebbe essere citato dalle risposte AI. Il referente consegna il file u5-seo-squadraN.zip.', null, '2027-04-13', (select id from topics where class_id = '5g' and title = 'SEO, Search Engine Optimization' limit 1), 'contenuti/compiti/seo-motori-ricerca.pdf', true where not exists (select 1 from assignments where class_id = '5g' and title = 'Farsi trovare (lavoro di gruppo)');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'L''audit di accessibilità (lavoro di gruppo)', 'La squadra fa l''audit di tre pagine del proprio sito con WAVE, Lighthouse, tastiera, screen reader, zoom e contrasti, riporta almeno otto problemi con il criterio WCAG, li corregge e rimisura, confronta gli alt generati dall''AI con i propri e scrive una breve dichiarazione di accessibilità. Il referente consegna il file u5-audit-squadraN.pdf.', null, '2027-04-16', (select id from topics where class_id = '5g' and title = 'Accessibilità e supporto ai disabili' limit 1), 'contenuti/compiti/accessibilita-web.pdf', true where not exists (select 1 from assignments where class_id = '5g' and title = 'L''audit di accessibilità (lavoro di gruppo)');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Online! Test, pubblicazione e consegna (lavoro di gruppo)', 'La squadra esegue un piano di almeno 15 test, valida le pagine, pubblica il sito su un hosting statico con HTTPS, documenta nslookup, curl e Lighthouse e scrive il piano di manutenzione per il cliente; ogni studente aggiunge una riflessione individuale. Il referente consegna il file u5-pubblicazione-squadraN.pdf con l''indirizzo del sito.', null, '2027-04-21', (select id from topics where class_id = '5g' and title = 'Test, pubblicazione e aggiornamento' limit 1), 'contenuti/compiti/pubblicare-sito.pdf', true where not exists (select 1 from assignments where class_id = '5g' and title = 'Online! Test, pubblicazione e consegna (lavoro di gruppo)');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il consulente sei tu', 'Intervista una piccola realtà che conosci e risali dal problema al vero bisogno con la tecnica dei 5 perché. In Calc scrivi almeno 12 requisiti classificati (F/NF, MoSCoW) con il criterio di accettazione, i vincoli e la risposta make or buy. Consegna il file requisiti-cognome.ods.', null, '2027-04-26', (select id from topics where class_id = '5g' and title = 'Processo di selezione' limit 1), 'contenuti/compiti/processo-selezione.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il consulente sei tu');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Indagine di mercato', 'Per il tuo cliente costruisci una long list di almeno 6 candidati con fonti e date, filtrala con i requisiti Must, valuta 4 fonti con il test CRAAP e scrivi una RFI di 8 domande. Consegna il file ricerca-cognome.ods con i fogli LongList, Fonti e RFI.', null, '2027-04-29', (select id from topics where class_id = '5g' and title = 'Processo di ricerca' limit 1), 'contenuti/compiti/ricerca-prodotti.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Indagine di mercato');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il vero prezzo', 'Scegli una categoria di software per uno studio di 10 persone e confronta 3 opzioni reali con licenze diverse: calcola in Calc il TCO su 3 anni con parametri, classifica le licenze e ricava dalle pagine ufficiali SLA, localizzazione dei dati ed esportazione. Consegna il file tco-cognome.ods.', null, '2027-05-04', (select id from topics where class_id = '5g' and title = 'Valutazione dei prodotti e dei fornitori' limit 1), 'contenuti/compiti/valutazione-fornitori.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il vero prezzo');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'La scelta motivata', 'Costruisci per il tuo cliente la matrice pesata in Calc: filtro dei Must, pesi motivati, descrittori, punteggi con MATR.SOMMA.PRODOTTO e analisi di sensibilità con il punto di svolta. Scrivi la relazione di scelta e consegna il file scelta-cognome.pdf.', null, '2027-05-10', (select id from topics where class_id = '5g' and title = 'Valutazione comparata' limit 1), 'contenuti/compiti/valutazione-comparata.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'La scelta motivata');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il mio primo accordo agile', 'Controlla una bozza di accordo di lavoro agile proposta da un''azienda inventata: per ogni clausola indica se è legittima, con l''articolo della legge 81/2017 o del DL 30/2021, riscrivi quelle non legittime e aggiungi due clausole che ti tutelerebbero. Consegna il file accordo-agile-cognome.pdf.', null, '2027-05-13', (select id from topics where class_id = '5g' and title = 'Lo smart working' limit 1), 'contenuti/compiti/smart-working.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il mio primo accordo agile');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'Il mio lavoro nel 2035', 'Scegli la professione che vorresti fare, scomponila in 8 mansioni con la classificazione europea ESCO e valuta quali saranno automatizzate, potenziate dall''AI o resteranno umane, usando due fonti affidabili e classificando uno strumento di AI secondo l''AI Act. Consegna il file lavoro-2035-cognome.pdf.', null, '2027-05-18', (select id from topics where class_id = '5g' and title = 'La robotica e il mondo del lavoro' limit 1), 'contenuti/compiti/robotica-lavoro.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il mio lavoro nel 2035');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '5g', 'La guida PA per neodiplomati', 'Scrivi una guida per chi si diplomerà l''anno prossimo con sei situazioni reali (università, ISEE, primo stipendio, medico, residenza, concorsi): per ognuna servizio, sito ufficiale, credenziale, passi e una truffa da evitare. Completa poi il programma Java che verifica un codice fiscale. Consegna il file guida-pa-cognome.zip con il PDF e CodiceFiscale.java.', null, '2027-05-21', (select id from topics where class_id = '5g' and title = 'Il rapporto con la Pubblica Amministrazione' limit 1), 'contenuti/compiti/pa-digitale.pdf', false where not exists (select 1 from assignments where class_id = '5g' and title = 'La guida PA per neodiplomati');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, group_work) select '5g', 'Progetto di gruppo: la casa domotica', 'In gruppo ripianificate il progetto della casa domotica del libro (obiettivi, ruoli, attività e tempi), sviluppate l''app di base e poi quella avanzata, e presentate i risultati alla classe. Consegnate un unico file casa-domotica-gruppo.zip con il codice sorgente, il piano del progetto in PDF e le slide della presentazione.', null, '2027-03-19', (select id from topics where class_id = '5g' and title = 'Learning by project: la casa domotica' limit 1), true where not exists (select 1 from assignments where class_id = '5g' and title = 'Progetto di gruppo: la casa domotica');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, group_work) select '5g', 'Progetto di gruppo: AB-Green e gli open data', 'In gruppo ripianificate il progetto AB-Green, cercate dataset sull''energia su dati.gov.it e data.europa.eu, integrateli nel sito usando le API CKAN e pubblicate il sito. Consegnate un unico file ab-green-gruppo.zip con il codice, un PDF che descrive i dataset usati e le chiamate API, e il link al sito pubblicato nella nota.', null, '2027-05-14', (select id from topics where class_id = '5g' and title = 'Learning by project: AB-Green' limit 1), true where not exists (select 1 from assignments where class_id = '5g' and title = 'Progetto di gruppo: AB-Green e gli open data');
insert into tests (class_id, position, title, description, test_date, practice_url) select '5g', 10, 'Verifica Unità 1: cybersecurity', 'Triade CIA, rischio come probabilità per impatto e trattamenti, profili degli attaccanti, Cyber Kill Chain e tattiche MITRE ATT&CK, ruoli del SOC, lettura di un log con un attacco a forza bruta, risposta agli incidenti e scadenze NIS2, firewall, DMZ, VPN e segmentazione, OWASP Top 10, categorie ed etica delle CTF.', '2026-11-27', 'contenuti/verifiche/5g-u1-simulazione.pdf' where not exists (select 1 from tests where class_id = '5g' and title = 'Verifica Unità 1: cybersecurity');
insert into test_files (test_id, test_url, solutions_url) select id, 'contenuti/verifiche/5g-u1-verifica-2ae1baa9d8.pdf', 'contenuti/verifiche/5g-u1-soluzioni-2ae1baa9d8.pdf' from tests where class_id = '5g' and title = 'Verifica Unità 1: cybersecurity' on conflict (test_id) do nothing;
insert into tests (class_id, position, title, description, test_date, practice_url) select '5g', 20, 'Verifica Unità 2: progettare e utilizzare web service', 'Sistemi distribuiti, RPC, architetture a servizi e microservizi, web service, XML e JSON, protocollo HTTP, SOAP e WSDL, SOAP in Java, REST, un servizio REST in Java, client Java e JSP, test con curl e Postman, fetch e CORS in JavaScript.', '2027-02-02', 'contenuti/verifiche/5g-u2-simulazione.pdf' where not exists (select 1 from tests where class_id = '5g' and title = 'Verifica Unità 2: progettare e utilizzare web service');
