insert into tests (class_id, position, title, description, test_date, practice_url) select '5g', 30, 'Verifica Unità 3: applicazioni Java per la comunicazione in rete', 'ICMP e ping, latenza, jitter e perdita, isReachable e ProcessBuilder, scansioni parallele con ExecutorService, Future e virtual thread, race condition, chat TCP multi-client e protocollo di testo, handshake e frame WebSocket, scelta motivata tra polling, SSE e WebSocket.', '2027-02-22', 'contenuti/verifiche/5g-u3-simulazione.pdf' where not exists (select 1 from tests where class_id = '5g' and title = 'Verifica Unità 3: applicazioni Java per la comunicazione in rete');
