insert into tests (class_id, position, title, description, test_date, practice_url) select '5g', 40, 'Verifica Unità 4: Applicazioni per sistemi mobili', 'Vincoli dei dispositivi mobili, architettura di Android, ciclo di vita, permessi, APK e AAB, Kotlin, layout, Button e Toast, Intent e Activity, con lettura e correzione di codice e il progetto di un''app.', '2027-03-23', 'contenuti/verifiche/5g-u4-simulazione.pdf' where not exists (select 1 from tests where class_id = '5g' and title = 'Verifica Unità 4: Applicazioni per sistemi mobili');
