insert into tests (class_id, position, title, description, test_date, practice_url) select '5g', 50, 'Verifica Unità 5: realizzare un sito web', 'Brief, obiettivi SMART e requisiti, mappa del sito e wireframe, responsive design, contrasto e Core Web Vitals, SEO con robots.txt, noindex e dati strutturati, accessibilità WCAG 2.2 e normativa, test, DNS, codici HTTP e pubblicazione, con un progetto di sito da disegnare.', '2027-04-26', 'contenuti/verifiche/5g-u5-simulazione.pdf' where not exists (select 1 from tests where class_id = '5g' and title = 'Verifica Unità 5: realizzare un sito web');
