insert into tests (class_id, position, title, description, test_date, practice_url) select '5g', 60, 'Verifica Unità 6: selezionare un prodotto informatico', 'Requisiti funzionali e non funzionali, MoSCoW, fonti e test CRAAP, RFI, RFP e RFQ, MePA, costo totale di possesso, licenze, SLA con RPO e RTO, GDPR e lock-in, matrice pesata con analisi di sensibilità e costo di un''API di AI.', '2027-05-14', 'contenuti/verifiche/5g-u6-simulazione.pdf' where not exists (select 1 from tests where class_id = '5g' and title = 'Verifica Unità 6: selezionare un prodotto informatico');
